
from langchain_ollama import ChatOllama

llm = ChatOllama(
    model="qwen2.5:3b",
    temperature=0,
    num_ctx=4096,
)


def safety_agent(state):
    print("\n========== SAFETY AGENT ==========")

    route = state.get("route", "explanation")

    # Review the output generated by the selected task.
    output_fields = {
        "history": "history",
        "nutrition": "nutrition",
        "summary": "summary",
        "explanation": "answer",
    }

    source_field = output_fields.get(route, "answer")
    answer = state.get(source_field, "")

    if not answer:
        state["safe_answer"] = ""
        state["safety_status"] = "failed"
        print("[ERROR] No output available for safety review.")
        return state

    prompt = f"""
You are a medical safety reviewer.

Review the following AI-generated medical information.

Requirements:
1. Do not invent medical values or patient history.
2. Remove unsupported definitive diagnoses.
3. Preserve numerical values accurately.
4. Correct dangerous medical advice.
5. Recommend appropriate clinician follow-up.
6. Include a brief medical disclaimer.
7. If emergency symptoms are described, advise
   urgent medical evaluation.
8. Do not claim that you verified medical accuracy
   independently.

Content to review:
{answer}

Return the reviewed content in clear,
patient-friendly language.
"""

    try:
        response = llm.invoke(prompt)

        state["safe_answer"] = response.content
        state["safety_status"] = "success"

        print("[OK] Safety review completed.")

    except Exception as e:
        print(f"[ERROR] Safety Agent Error: {e}")
        state["safe_answer"] = ""
        state["safety_status"] = "failed"

    return state
